begin;
create temporary table test_ids(name text primary key,id uuid not null default gen_random_uuid()) on commit drop;
insert into test_ids(name) select unnest(array['admin','learner_a','learner_b','trainer','employer_a','employer_b','va_a','va_b','bootstrap','program','module','lesson','cohort_a','cohort_b','assignment_a','assignment_b','org_a','org_b','request_a','request_b','match_a','placement_a','placement_b','task_a','timesheet_a','ticket_a','ticket_b','notification_a','notification_b','scenario','session_a','session_b']);
grant select on test_ids to authenticated,anon;
create function pg_temp.fixture(name text) returns uuid language sql stable as $$ select id from pg_temp.test_ids where name=$1 $$;
create temporary table test_results(name text,passed boolean) on commit drop;
grant select,insert on test_results to authenticated,anon;
create function pg_temp.assert_true(condition boolean,label text) returns void language plpgsql as $$ begin if condition is not true then raise exception 'FAILED: %',label; end if; insert into pg_temp.test_results values(label,true); end $$;
create function pg_temp.expect_denied(command text,label text) returns void language plpgsql as $$ declare denied boolean:=false; begin begin execute command; exception when insufficient_privilege or check_violation or raise_exception then denied:=true; end; perform pg_temp.assert_true(denied,label); end $$;
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_user_meta_data,is_anonymous)
select id,'authenticated','authenticated',name||'-'||id||'@example.invalid',now(),jsonb_build_object('display_name','Integration '||name,'role','admin'),false from test_ids where name in ('admin','learner_a','learner_b','trainer','employer_a','employer_b','va_a','va_b');
select pg_temp.assert_true((select role='applicant' from public.platform_profiles where user_id=pg_temp.fixture('learner_a')),'Signup ignores forged role metadata');
update public.platform_profiles set role=case when user_id=pg_temp.fixture('admin') then 'admin' when user_id=pg_temp.fixture('trainer') then 'trainer' when user_id in (pg_temp.fixture('employer_a'),pg_temp.fixture('employer_b')) then 'employer' when user_id in (pg_temp.fixture('va_a'),pg_temp.fixture('va_b')) then 'medical_va' else 'applicant' end where user_id in(select id from test_ids where name in ('admin','learner_a','learner_b','trainer','employer_a','employer_b','va_a','va_b'));
insert into private.bootstrap_admin_emails(email) values('bootstrap-'||pg_temp.fixture('bootstrap')::text||'@example.invalid');
insert into auth.users(id,aud,role,email,raw_user_meta_data,is_anonymous) values(pg_temp.fixture('bootstrap'),'authenticated','authenticated','bootstrap-'||pg_temp.fixture('bootstrap')::text||'@example.invalid','{}',false);
select pg_temp.assert_true((select role='applicant' from public.platform_profiles where user_id=pg_temp.fixture('bootstrap')),'Unconfirmed owner address receives no administrator access');
update auth.users set email_confirmed_at=now() where id=pg_temp.fixture('bootstrap');
select pg_temp.assert_true((select role='admin' from public.platform_profiles where user_id=pg_temp.fixture('bootstrap')),'Only verified approved owner address bootstraps administrator');
insert into public.training_programs(id,title,status) values(pg_temp.fixture('program'),'RLS QA program','published');
insert into public.program_modules(id,program_id,title,position) values(pg_temp.fixture('module'),pg_temp.fixture('program'),'QA Module',1);
insert into public.training_lessons(id,module_id,title,position,status) values(pg_temp.fixture('lesson'),pg_temp.fixture('module'),'QA Lesson',1,'published');
insert into public.training_cohorts(id,title,program_id,capacity) values(pg_temp.fixture('cohort_a'),'QA cohort A',pg_temp.fixture('program'),1),(pg_temp.fixture('cohort_b'),'QA cohort B',pg_temp.fixture('program'),30);
insert into public.cohort_enrollments(cohort_id,trainee_id) values(pg_temp.fixture('cohort_a'),pg_temp.fixture('learner_a')),(pg_temp.fixture('cohort_b'),pg_temp.fixture('learner_b'));
select pg_temp.expect_denied(format('insert into public.cohort_enrollments(cohort_id,trainee_id) values(%L,%L)',pg_temp.fixture('cohort_a'),pg_temp.fixture('learner_b')),'Cohort capacity is enforced');
insert into public.cohort_trainers(cohort_id,trainer_id) values(pg_temp.fixture('cohort_a'),pg_temp.fixture('trainer'));
insert into public.training_assignments(id,cohort_id,title) values(pg_temp.fixture('assignment_a'),pg_temp.fixture('cohort_a'),'QA A'),(pg_temp.fixture('assignment_b'),pg_temp.fixture('cohort_b'),'QA B');
insert into public.employer_organizations(id,name,country) values(pg_temp.fixture('org_a'),'QA Organization A','Kenya'),(pg_temp.fixture('org_b'),'QA Organization B','Canada');
insert into public.organization_memberships(organization_id,user_id) values(pg_temp.fixture('org_a'),pg_temp.fixture('employer_a')),(pg_temp.fixture('org_b'),pg_temp.fixture('employer_b'));
insert into public.candidate_profiles(user_id,display_name,published) values(pg_temp.fixture('learner_a'),'QA learner A',true),(pg_temp.fixture('learner_b'),'QA learner B',true);
insert into public.staffing_requests(id,organization_id,title,requirements,created_by) values(pg_temp.fixture('request_a'),pg_temp.fixture('org_a'),'QA request A','Synthetic requirements',pg_temp.fixture('employer_a')),(pg_temp.fixture('request_b'),pg_temp.fixture('org_b'),'QA request B','Synthetic requirements',pg_temp.fixture('employer_b'));
insert into public.candidate_matches(id,request_id,candidate_id) values(pg_temp.fixture('match_a'),pg_temp.fixture('request_a'),pg_temp.fixture('learner_a'));
insert into public.placements(id,request_id,medical_va_id,title,start_date) values(pg_temp.fixture('placement_a'),pg_temp.fixture('request_a'),pg_temp.fixture('va_a'),'QA VA A',current_date),(pg_temp.fixture('placement_b'),pg_temp.fixture('request_b'),pg_temp.fixture('va_b'),'QA VA B',current_date);
insert into public.va_tasks(id,placement_id,title,created_by) values(pg_temp.fixture('task_a'),pg_temp.fixture('placement_a'),'QA task A',pg_temp.fixture('employer_a'));
insert into public.timesheets(id,placement_id,user_id,work_date,minutes_worked,description) values(pg_temp.fixture('timesheet_a'),pg_temp.fixture('placement_a'),pg_temp.fixture('va_a'),current_date,60,'QA time');
insert into public.support_tickets(id,owner_id,title,description) values(pg_temp.fixture('ticket_a'),pg_temp.fixture('learner_a'),'QA ticket A','QA request'),(pg_temp.fixture('ticket_b'),pg_temp.fixture('learner_b'),'QA ticket B','QA request');
insert into public.notifications(id,user_id,title) values(pg_temp.fixture('notification_a'),pg_temp.fixture('learner_a'),'QA notification A'),(pg_temp.fixture('notification_b'),pg_temp.fixture('learner_b'),'QA notification B');
insert into public.simulation_scenarios(id,title,instructions,status) values(pg_temp.fixture('scenario'),'QA synthetic scheduling','Fictional administrative conversation','published');
insert into public.simulation_sessions(id,scenario_id,trainee_id,cohort_id) values(pg_temp.fixture('session_a'),pg_temp.fixture('scenario'),pg_temp.fixture('learner_a'),pg_temp.fixture('cohort_a')),(pg_temp.fixture('session_b'),pg_temp.fixture('scenario'),pg_temp.fixture('learner_b'),pg_temp.fixture('cohort_b'));

set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fixture('learner_a'),'role','authenticated')::text,true);
select pg_temp.assert_true((select count(*)=1 from public.platform_profiles),'Learner sees only own profile');
select pg_temp.assert_true((select count(*)=1 from public.cohort_enrollments),'Learner sees only own enrollment');
select pg_temp.assert_true((select count(*)=1 from public.training_assignments),'Learner sees only enrolled assignments');
select pg_temp.assert_true((select count(*)=1 from public.support_tickets),'Learner sees only own support ticket');
with saved as (insert into public.support_tickets(title,description) values('QA returned ticket','Synthetic support') returning id) select pg_temp.assert_true((select count(*)=1 from saved),'Ticket insert can return its authorized row');
select pg_temp.assert_true((select count(*)=1 from public.notifications),'Learner sees only own notification');
select pg_temp.assert_true((select count(*)=1 from public.simulation_sessions),'Learner sees only own simulation');
select pg_temp.expect_denied(format('update public.platform_profiles set role=''admin'' where user_id=%L',pg_temp.fixture('learner_a')),'Learner cannot elevate own role');
insert into public.lesson_progress(lesson_id,user_id,completed,completed_at) values(pg_temp.fixture('lesson'),pg_temp.fixture('learner_a'),true,now());
select pg_temp.assert_true((select count(*)=1 from public.lesson_progress where completed),'Own lesson progress persists');
select pg_temp.expect_denied(format('insert into public.lesson_progress(lesson_id,user_id,completed) values(%L,%L,true)',pg_temp.fixture('lesson'),pg_temp.fixture('learner_b')),'Learner cannot write another learner progress');
insert into public.assignment_submissions(assignment_id,trainee_id,response) values(pg_temp.fixture('assignment_a'),pg_temp.fixture('learner_a'),'Synthetic submission');
select pg_temp.expect_denied(format('update public.assignment_submissions set score=100 where trainee_id=%L',pg_temp.fixture('learner_a')),'Learner cannot self-grade');
select pg_temp.expect_denied(format('insert into public.assignment_submissions(assignment_id,trainee_id,response) values(%L,%L,''forged'')',pg_temp.fixture('assignment_b'),pg_temp.fixture('learner_a')),'Learner cannot submit to an unenrolled cohort');
select pg_temp.expect_denied(format('insert into public.organization_memberships(organization_id,user_id) values(%L,%L)',pg_temp.fixture('org_b'),pg_temp.fixture('learner_a')),'Users cannot grant themselves organization membership');
select pg_temp.expect_denied(format('insert into public.activity_events(actor_id,entity_type,entity_id,action,summary) values(%L,''fake'',''fake'',''insert'',''fake'')',pg_temp.fixture('learner_a')),'Client cannot forge audit events');
update public.notifications set read_at=now() where id=pg_temp.fixture('notification_a');
select pg_temp.assert_true((select read_at is not null from public.notifications where id=pg_temp.fixture('notification_a')),'Notification acknowledgement persists');
select pg_temp.expect_denied(format('update public.notifications set body=''forged'' where id=%L',pg_temp.fixture('notification_a')),'Notification body cannot be forged');
select pg_temp.expect_denied(format('insert into public.simulation_evaluations(session_id,reviewer_id,score,feedback) values(%L,%L,100,''self'')',pg_temp.fixture('session_a'),pg_temp.fixture('learner_a')),'Learner cannot self-evaluate simulations');

select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fixture('trainer'),'role','authenticated')::text,true);
select pg_temp.assert_true((select count(*)=1 from public.training_cohorts),'Trainer sees only assigned cohort');
select pg_temp.assert_true((select count(*)=1 from public.assignment_submissions),'Trainer sees only assigned learner submissions');
update public.assignment_submissions set score=85,feedback='QA reviewed' where trainee_id=pg_temp.fixture('learner_a');
select pg_temp.assert_true((select score=85 from public.assignment_submissions where trainee_id=pg_temp.fixture('learner_a')),'Assigned trainer can grade a submission');
insert into public.simulation_evaluations(session_id,score,feedback) values(pg_temp.fixture('session_a'),80,'QA evaluation');
select pg_temp.expect_denied(format('insert into public.simulation_evaluations(session_id,score,feedback) values(%L,80,''QA'')',pg_temp.fixture('session_b')),'Trainer cannot evaluate another cohort');

select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fixture('employer_a'),'role','authenticated')::text,true);
select pg_temp.assert_true((select count(*)=1 from public.employer_organizations),'Employer sees only own organization');
select pg_temp.assert_true((select count(*)=1 from public.staffing_requests),'Employer sees only own staffing requests');
select pg_temp.assert_true((select count(*)=1 from public.placements),'Employer sees only own placements');
select pg_temp.assert_true((select count(*)=1 from public.candidate_profiles),'Employer sees only explicitly matched published candidate');
with saved as (insert into public.staffing_requests(organization_id,title,requirements) values(pg_temp.fixture('org_a'),'QA returned request','Synthetic requirements') returning id) select pg_temp.assert_true((select count(*)=1 from saved),'Employer request insert can return its authorized row');
select pg_temp.expect_denied(format('insert into public.va_tasks(placement_id,title) values(%L,''Foreign task'')',pg_temp.fixture('placement_b')),'Employer cannot create tasks for another organization');
select pg_temp.expect_denied(format('update public.candidate_matches set request_id=%L where id=%L',pg_temp.fixture('request_b'),pg_temp.fixture('match_a')),'Employer cannot move a candidate match across organizations');

select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fixture('va_a'),'role','authenticated')::text,true);
select pg_temp.assert_true((select count(*)=1 from public.placements),'Medical VA sees only own placement');
update public.va_tasks set status='done',notes='QA complete' where id=pg_temp.fixture('task_a');
select pg_temp.assert_true((select status='done' from public.va_tasks where id=pg_temp.fixture('task_a')),'Medical VA can update own task progress');
select pg_temp.expect_denied(format('update public.va_tasks set title=''forged'' where id=%L',pg_temp.fixture('task_a')),'Medical VA cannot rewrite employer task instructions');
select pg_temp.expect_denied(format('update public.timesheets set status=''approved'' where id=%L',pg_temp.fixture('timesheet_a')),'Medical VA cannot approve own timesheet');
update public.timesheets set status='submitted' where id=pg_temp.fixture('timesheet_a');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fixture('employer_a'),'role','authenticated')::text,true);
update public.timesheets set status='approved' where id=pg_temp.fixture('timesheet_a');
select pg_temp.assert_true((select status='approved' from public.timesheets where id=pg_temp.fixture('timesheet_a')),'Employer can approve submitted own-organization timesheet');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fixture('va_a'),'role','authenticated')::text,true);
select pg_temp.expect_denied(format('update public.timesheets set minutes_worked=120 where id=%L',pg_temp.fixture('timesheet_a')),'Approved timesheet cannot be altered by its author');

reset role;
select set_config('request.jwt.claims','{}',true);
set local role anon;
select pg_temp.expect_denied('select * from public.platform_profiles','Anonymous profile reads denied');
select pg_temp.expect_denied('select * from public.candidate_applications','Anonymous application reads denied');
select pg_temp.expect_denied('select * from public.employer_enquiries','Anonymous enquiry reads denied');
select pg_temp.expect_denied('select * from public.documents','Anonymous file metadata reads denied');
select pg_temp.expect_denied('select * from public.simulation_sessions','Anonymous simulation reads denied');
insert into public.candidate_applications(full_name,email,phone,country,medical_background,experience_years,motivation) values('QA anonymous applicant','qa@example.invalid','0000','Kenya','Synthetic','0','Synthetic test motivation with enough characters.');
select pg_temp.assert_true(true,'Anonymous public intake remains insert-only');
select pg_temp.expect_denied('insert into public.candidate_applications(full_name,email,phone,country,medical_background,experience_years,motivation,user_id) values(''QA'',''qa@example.invalid'',''000'',''Kenya'',''QA'',''0'',''Synthetic test motivation goes here.'',gen_random_uuid())','Anonymous applicant cannot assign a user identity');
reset role;
select jsonb_build_object('passed',count(*),'failed',count(*) filter(where not passed),'private_bucket',(select not public from storage.buckets where id='dialife-private'),'app_tables',(select count(*) from pg_tables where schemaname='public'),'all_tables_have_rls',(select bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),'anonymous_select_denied_on_all_tables',(select bool_and(not has_table_privilege('anon',c.oid,'SELECT')) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r')) as test_result from test_results;
rollback;
